  Ciphertext p5 = z * c5;
  Ciphertext p3x3 = p3 + p3;
  p3x3 = p3x3 + p3;
  Ciphertext p5x4 = p5 + p5;
  p5x4 = p5x4 + p5x4;
  Ciphertext p5x5 = p5 + p5x4;
  Ciphertext lin = p1 + p5x5;
  lin = lin - p3x3;

  // z^3 part: (4c3 - 20c5) * z^3.
  Ciphertext q3 = z3 * c3;
  Ciphertext q5 = z3 * c5;
  Ciphertext a4 = q3 + q3;
  a4 = a4 + a4;
  Ciphertext q4 = q5 + q5;
  q4 = q4 + q4;
  Ciphertext q16 = q4 + q4;
  q16 = q16 + q16;
  Ciphertext t20 = q16 + q4;
  Ciphertext cub = a4 - t20;

  // z^5 part: 16 c5 * z^5.
  Ciphertext r5 = z5 * c5;
  Ciphertext b16 = r5 + r5;
  b16 = b16 + b16;
  b16 = b16 + b16;
  b16 = b16 + b16;

  Ciphertext result = lin + cub;
  result = result + b16;
