  z3x4 = z3x4 + z3x4;
  Ciphertext z3x8 = z3x4 + z3x4;
  Ciphertext z3x16 = z3x8 + z3x8;
  Ciphertext z3x20 = z3x16 + z3x4;

  // 16 z^5
